style.css:
/* Rainbow Roblox Dreamland — roblox.com */

:root {
  /* swap these colors whenever you like */
  --my-sky: #36baff;
  --my-pink: #ff79dc;
  --my-blue: #168cff;
}

/* dreamy rainbow background */
html,
body {
  min-height: 100% !important;
  background-color: var(--my-sky) !important;
}

body {
  background-image: url("https://i.pinimg.com/736x/b2/71/66/b271664414dcd99479e8cda6e59ade47.jpg") !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  background-size: cover !important;
  background-attachment: fixed !important;
}
